from pathlib import Path
import json,html
P=Path(__file__).parent

def block(name,attrs,markup):
 a=' '+json.dumps(attrs,ensure_ascii=False,separators=(',',':')) if attrs else ''
 return f'<!-- wp:{name}{a} -->\n{markup}\n<!-- /wp:{name} -->\n'
def para(s,cls=''):
 return block('paragraph',{'className':cls} if cls else {},f'<p'+(f' class="{cls}"' if cls else '')+f'>{s}</p>')
def h(s,n=2):return block('heading',{'level':n} if n!=2 else {},f'<h{n} class="wp-block-heading">{s}</h{n}>')
def group(s,cls=''):
 return block('group',{'className':cls,'layout':{'type':'default'}},f'<div class="wp-block-group {cls}">{s}</div>')
def cols(*items):
 return block('columns',{},'<div class="wp-block-columns">'+''.join(block('column',{},'<div class="wp-block-column">'+s+'</div>') for s in items)+'</div>')
def image(n,alt):
 ext='png' if n in ['logo','kindy','dumplings'] else 'jpg'
 return block('image',{'sizeSlug':'full','linkDestination':'none'},f'<figure class="wp-block-image size-full"><img src="@@ASSET@@/{n}.{ext}" alt="{html.escape(alt)}"/></figure>')
def button(s,key,outline=False):
 cls='wp-block-button'+(' is-style-outline' if outline else '')
 return block('button',{'className':'is-style-outline'} if outline else {},f'<div class="{cls}"><a class="wp-block-button__link wp-element-button" href="@@PAGE:{key}@@">{s}</a></div>')
def buttons(*items):return block('buttons',{},'<div class="wp-block-buttons">'+''.join(items)+'</div>')
def short(s):return block('shortcode',{},s)
def link(s,key):return f'<a href="@@PAGE:{key}@@">{s}</a>'
def listing(items):return block('list',{},'<ul class="wp-block-list">'+''.join(block('list-item',{},'<li>'+i+'</li>')for i in items)+'</ul>')
def intro(label,title,desc):return group(para(label,'tkc-label')+h(title,1)+para(desc),'tkc-section tkc-page-intro')
def page(label,title,desc,body):return intro(label,title,desc)+group(body,'tkc-body')
def form(key,lang):return short(f'@@FORM:{key}:{lang}@@')
def details(title,body):return block('details',{},'<details class="wp-block-details"><summary>'+title+'</summary>'+body+'</details>')
def note(s):return group(para(s),'tkc-note')
def sectionhead(title,ltext='',key='activities'):return group(h(title)+(para(link(ltext,key)) if ltext else ''),'tkc-section-head')
