add('activities','Activities','Tegevused',page('Meet. Share. Discover.','Good company, shared experiences.','From a cup of tea to an afternoon outdoors, find a way to connect that feels right for you.',h('Upcoming activities')+short('[tkc_events scope="future"]')+h('Past activities')+para('A few moments from our community story. Earlier activities helped shape The Kind Circle before its formal establishment as an MTÜ.')+short('[tkc_past_activities]')),page('Kohtu. Jaga. Avasta.','Hea seltskond, ühised kogemused.','Tassikesest teest kuni ühise retkeni: leia endale sobiv viis teistega ühenduse loomiseks.',h('Tulevased tegevused')+short('[tkc_events scope="future"]')+h('Varasemad tegevused')+para('Hetki meie kogukonna loost. Varasemad algatused aitasid kujundada The Kind Circle’i enne selle ametlikku asutamist MTÜ-na.')+short('[tkc_past_activities]')))
add('about-us','About us','Meist',page('The Kind Circle MTÜ','A community built on small acts of kindness.','We bring local residents and newcomers together through shared experiences, cultural exchange and practical mutual support.',h('Everyone has something to share.')+para('Moving somewhere new can mean finding your way through unfamiliar systems, languages and everyday life. It can also mean missing the simple comfort of knowing people nearby. Local residents, too, benefit from opportunities to meet international neighbours and discover different cultures.')+para('We see integration as a two-way process. Through approachable activities and shared interests, we create opportunities to meet as equals, learn from one another and contribute to life in Tallinn.')+h('Our story')+para('The Kind Circle grew from a student-led initiative in 2023 and the founder’s experience organising Chinese- and Korean-related activities while studying at the University of Tartu. Those early experiences inspired a broader community open to people from all backgrounds.')+para('Today, The Kind Circle MTÜ is a nonprofit organisation based in Tallinn. Our guiding words are simple: Share. Connect. Support.')+h('What we work towards')+listing(['Practical knowledge sharing for newcomers navigating everyday life in Estonia.','Local discovery, cultural experiences and opportunities to connect with Tallinn.','Outdoor activities and shared experiences that make meeting people feel natural.','Language learning and intercultural exchange between international and local communities.','Shared reading and cultural resources, developed as space and resources become available.'])+h('Participation, at your own pace')+para('You do not need to be outgoing, arrive with friends, or have everything figured out. We aim to offer welcoming, low-pressure ways to take part, respecting different needs and backgrounds.')+image('hiking','Community members on a shared outdoor activity')+h('Meet Kindy')+para('Our friendly blue pony represents kindness, connection, curiosity and belonging. Kindy reminds us that even a small hello can be the beginning of something good.')+image('kindy','Kindy mascot in sixteen poses')+buttons(button('Find an activity','activities'),button('Get involved','get-involved',True))),page('The Kind Circle MTÜ','Kogukond, mis kasvab väikestest heategudest.','Toome kohalikud elanikud ja uustulnukad kokku ühiste kogemuste, kultuurivahetuse ja praktilise vastastikuse toe kaudu.',h('Igaühel on midagi jagada.')+para('Uude kohta kolimine tähendab sageli võõraste süsteemide, keelte ja igapäevaeluga kohanemist. Puudust võib tunda ka lihtsast kindlustundest, et läheduses on tuttavaid inimesi. Ka kohalikele elanikele pakuvad rahvusvaheliste naabritega kohtumised võimalust avastada teisi kultuure.')+para('Näeme lõimumist kahepoolse protsessina. Lihtsate tegevuste ja ühiste huvide kaudu loome võimalusi kohtuda võrdsetena, õppida üksteiselt ja panustada Tallinna ellu.')+h('Meie lugu')+para('The Kind Circle kasvas välja 2023. aastal alanud tudengialgatusest ning asutaja kogemusest hiina ja korea kultuuriga seotud tegevuste korraldamisel Tartu Ülikoolis õppimise ajal. Neist kogemustest sündis soov luua laiem kogukond, mis on avatud kõigile.')+para('Täna on The Kind Circle MTÜ Tallinnas tegutsev mittetulundusühing. Meie juhtmõte on lihtne: jaga, loo sidemeid ja toeta.')+h('Meie tegevussuunad')+listing(['Praktiliste teadmiste jagamine Eestis igapäevaeluga kohanevatele uustulnukatele.','Tallinna avastamine, kultuurikogemused ja sidemed kohaliku eluga.','Õuetegevused ja ühised kogemused, mis muudavad tutvumise loomulikuks.','Keeleõpe ja kultuurivahetus kohalike ning rahvusvaheliste kogukondade vahel.','Ühine lugemine ja kultuuriressursid vastavalt ruumide ja vahendite võimalustele.'])+h('Osalemine sinu enda tempos')+para('Sa ei pea olema väga seltskondlik, tulema koos sõpradega ega kõike ette teadma. Soovime pakkuda sõbralikke ja pingevabu osalemisviise, arvestades erinevate vajaduste ja taustadega.')+image('hiking','Kogukonnaliikmed ühisel õuetegevusel')+h('Saage tuttavaks: Kindy')+para('Meie sõbralik sinine poni sümboliseerib headust, ühendust, uudishimu ja kuuluvust. Kindy tuletab meelde, et ka väike tere võib olla millegi hea algus.')+image('kindy','Kindy maskott kuueteistkümnes poosis')+buttons(button('Leia tegevus','activities'),button('Löö kaasa','get-involved',True))))
roles_en=[('Local community liaison','Help research venues and local resources, build relationships with community organisations, and connect residents with newcomers.','Good English and Estonian communication; an interest in community development and cultural exchange. Relevant outreach experience is welcome.'),('Event planning and delivery','Support activity ideas, scheduling, practical preparation, participant communication and welcoming people on the day.','Good English and Estonian, organisation and attention to detail. Students are welcome; previous experience is helpful but not essential.'),('Social media and communications','Prepare activity announcements and accessible content, support social channels and keep our communications clear and welcoming.','English and a relevant local language, such as Estonian or Russian, with suitable writing skills. Experience with content or communications is preferred.'),('Creative and materials support','Help with photography, video, simple design, posters, activity materials and organising creative resources.','Good English and an interest in creative or practical work. Relevant experience or a portfolio is welcome.')]
